/**
 *  前端展示用的 Skill DTO。
 * 
 *  合并了扫描结果（SkillRecord）+ 激活状态（全局禁用/会话级 enabled）。
 */
export type SkillDto = {
	name: string,
	description: string,
	source: SkillSource,
	disable_model_invocation: boolean,
	license: string | null,
	compatibility: string | null,
	allowed_tools: string[] | null,
	/**
	 *  本会话是否激活（会话级 enabled 状态；None=无会话级记录，按 source 默认行为）。
	 *  前端据此显示开关初始态。
	 */
	conversation_enabled: boolean | null,
	/**  是否全局禁用（层次 2）。 */
	globally_disabled: boolean,
};

/**
 *  Skill 来源（对应 conversation_skills.source 列）。
 * 
 *  kebab-case 序列化，specta 导出为 TS 字符串字面量联合类型。
 */
export type SkillSource = 
/**  随应用分发，只读（resource_dir/skills/） */
"builtin" | 
/**  用户导入，可读写（~/.onto-studio/skills/） */
"imported" | 
/**  跨客户端扫描，只读（~/.agents/skills/ 等） */
"external-read-only" | 
/**  项目级（二期，需先定义"工作区"概念） */
"project";

/**  流式 chunk 种类。 */
export type StreamKind = 
/**  文本增量 */
"text_delta" | 
/**  思考/reasoning 增量（reasoning 模型） */
"reasoning_delta" | 
/**
 *  工具调用开始（模型决定调用某工具，即将执行）
 *  `text` = 工具名；`tool_call` 附带调用详情
 */
"tool_call_start" | 
/**
 *  工具调用结果（执行完成）
 *  `text` = 结果文本（模型可见）；`tool_call` 附带调用详情与结果
 */
"tool_call_result" | 
/**
 *  provider 报告的真实 token usage（二期 B1）
 *  `usage` 附带输入/输出/总 token；可在 Done 前多次发出（多轮工具调用）
 */
"usage" | 
/**  流式正常结束 */
"done" | 
/**  出错结束 */
"error";

